using Hospital.Web.Data; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore;
var b=WebApplication.CreateBuilder(args); b.Services.AddControllersWithViews(); b.Services.AddDbContext<AppDbContext>(o=>o.UseNpgsql(b.Configuration.GetConnectionString("DefaultConnection"))); b.Services.AddDefaultIdentity<IdentityUser>(o=>o.SignIn.RequireConfirmedAccount=false).AddRoles<IdentityRole>().AddEntityFrameworkStores<AppDbContext>(); var app=b.Build(); app.UseStaticFiles(); app.UseRouting(); app.UseAuthentication(); app.UseAuthorization(); app.MapControllerRoute(name:"default",pattern:"{controller=Home}/{action=Index}/{id?}"); app.Run();
